import React, { useState } from 'react';

function App() {
  const [fullName, setFullName] = useState({
    fname : '',
    lname : '',
    email : '',
    mobile : ''
  });

  const inputEvent = (event)=>{

    // const inputEvent = (event) => {
    //   const { name, value } = event.target;

    //   setFullName((preValue) => ({
    //     ...preValue,  // Keep the old values
    //     [name]: value,  // Update only the changed field
    //   }));
    // };

    const value = event.target.value;
    const name = event.target.name;

    setFullName((preValue)=>{
      if(name === 'fName'){
        return{
          fname : value,
          lname : preValue.lname
        };
      }else if(name === 'lName'){
        return{
          fname : preValue.fname,
          lname : value
        };
      }

    });

  };
  const submit = (event) => {
      event.preventDefault();
  };

  return (
    <>
      <div className='main'>
        <form onSubmit={submit}>
          <div className='textarea'>
              Hello {fullName.fname} {fullName.lname}<br/>
              {fullName.email}<br/>
              {fullName.mobile}
          </div><br/>
          <input type='text' 
          placeholder='firstName' 
          onChange={inputEvent} 
          name = 'fName'
          value = {fullName.fname}
          className='input'/>
          <br/><br/>
          <input type='text' 
          placeholder='LastName' 
          onChange={inputEvent} 
          name = 'lName'
          value = {fullName.lname}
          className='input'/>
          <br/><br/>
          <input type='email' 
          placeholder='Email' 
          onChange={inputEvent} 
          name = 'email'
          value = {fullName.email}
          className='input'/>
          <br/><br/>
          <input type='number' 
          placeholder='Mobile' 
          onChange={inputEvent} 
          name = 'mobile'
          value = {fullName.mobile}
          className='input'/>
          <br/><br/>
          <button  type='submit' className='btn'>Submit</button>
        </form>  
      </div>
    </>
  );
}

export default App;
